import{_ as t,o as d,c as o,ah as a}from"./chunks/framework.C-FRNfAJ.js";const h=JSON.parse('{"title":"Intégrations","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/integrations.md","filePath":"src/guide/integrations.md"}'),r={name:"guide/integrations.md"};function n(s,e,c,i,u,l){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="integrations" tabindex="-1">Intégrations <a class="header-anchor" href="#integrations" aria-label="Permalink to &quot;Intégrations&quot;">​</a></h1><p>Kura est au centre de trois flux : le site NextBoxx lui <strong>envoie</strong> des candidatures, demandes et inscriptions ; Sève lui <strong>délivre</strong> l&#39;identité et reçoit ses changements ; WhatsApp et PayGate complètent les notifications et les paiements.</p><h2 id="api-du-site-nextboxx" tabindex="-1">API du site NextBoxx <a class="header-anchor" href="#api-du-site-nextboxx" aria-label="Permalink to &quot;API du site NextBoxx&quot;">​</a></h2><p>Le site appelle Kura <strong>depuis son serveur</strong>, jamais depuis le navigateur, avec une clé d&#39;API dédiée dans l&#39;en-tête <code>Authorization: Bearer &lt;clé&gt;</code>. La clé est <code>NEXTBOXX_SITE_API_KEY</code> côté Kura, <code>KURA_SITE_API_KEY</code> côté site. Limite : 60 requêtes par minute.</p><table tabindex="0"><thead><tr><th>Méthode</th><th>Endpoint</th><th>Effet</th></tr></thead><tbody><tr><td><code>POST</code></td><td><code>/api/candidatures</code></td><td>Crée ou réutilise le compte, ouvre la candidature, renvoie <code>tracking_token</code></td></tr><tr><td><code>GET</code></td><td><code>/api/candidatures/status</code></td><td>État d&#39;un dossier à partir du <code>tracking_token</code>, sans rapatrier les données</td></tr><tr><td><code>GET</code></td><td><code>/api/events</code></td><td>Événements publiés à venir, avec places restantes et date limite de paiement</td></tr><tr><td><code>POST</code></td><td><code>/api/events/{event}/registrations</code></td><td>Inscrit un participant, confirme, met en attente de paiement ou en liste d&#39;attente</td></tr><tr><td><code>POST</code></td><td><code>/api/company-requests</code></td><td>Dépose une demande de formation B2B</td></tr><tr><td><code>GET</code></td><td><code>/api/partnerships</code></td><td>Partenariats technologiques actifs, par référentiel</td></tr></tbody></table><p>Codes de réponse notables :</p><ul><li><code>401</code> : clé absente ou invalide.</li><li><code>409</code> : <code>COOLING_OFF</code> (redépôt trop tôt après un refus), <code>CANDIDATURE_IN_PROGRESS</code>, <code>EVENT_CLOSED</code>, <code>ALREADY_REGISTERED</code>, <code>ACCOUNT_SUSPENDED</code>.</li><li><code>422</code> : validation (référentiel inconnu ou non publié, format non proposé, code apporteur invalide…).</li></ul><p>Une réponse acceptée est copiée dans le CMS du site avec son identifiant ; en cas d&#39;erreur, le site ne conserve rien et le candidat resoumet.</p><h2 id="oauth2-openid-connect-pour-seve" tabindex="-1">OAuth2 / OpenID Connect pour Sève <a class="header-anchor" href="#oauth2-openid-connect-pour-seve" aria-label="Permalink to &quot;OAuth2 / OpenID Connect pour Sève&quot;">​</a></h2><p>Kura est le fournisseur d&#39;identité. Sève ne stocke aucun mot de passe Moodle.</p><table tabindex="0"><thead><tr><th>Endpoint</th><th>Rôle</th></tr></thead><tbody><tr><td><code>GET /oauth2/authorize</code></td><td>Redirige vers la connexion Kura, puis vers Sève avec un code</td></tr><tr><td><code>POST /oauth2/token</code></td><td>Échange le code contre un jeton d&#39;accès (1 h) et un jeton de rafraîchissement (30 jours)</td></tr><tr><td><code>GET /oauth2/userinfo</code></td><td>Renvoie <code>sub</code>, <code>email</code>, <code>email_verified</code>, <code>name</code>, <code>given_name</code>, <code>family_name</code></td></tr></tbody></table><ul><li>Client enregistré par <code>php artisan seve:client</code>, avec l&#39;URL de retour <code>{SEVE_URL}/admin/oauth2callback.php</code>. Le secret n&#39;est affiché qu&#39;une fois.</li><li>Seuls les comptes <code>actif</code> ou <code>canope</code> peuvent se connecter ; un compte <code>suspendu</code> reçoit <code>403</code>.</li><li>Pas de jeton d&#39;identité OpenID Connect : Moodle lit <code>userinfo</code> et rapproche les comptes par email.</li><li>Les clés OAuth (<code>storage/oauth-*.key</code>) sont critiques : les perdre déconnecte tous les utilisateurs de Sève.</li></ul><h2 id="web-services-seve" tabindex="-1">Web services Sève <a class="header-anchor" href="#web-services-seve" aria-label="Permalink to &quot;Web services Sève&quot;">​</a></h2><p>Kura appelle Sève ; Sève n&#39;appelle pas Kura. Les appels passent par un service externe « Intégration Kura », avec le token d&#39;un compte de service (<code>SEVE_WS_TOKEN</code>), en REST.</p><h3 id="provisionnement" tabindex="-1">Provisionnement <a class="header-anchor" href="#provisionnement" aria-label="Permalink to &quot;Provisionnement&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Fonction Moodle</th><th>Déclencheur</th></tr></thead><tbody><tr><td><code>core_user_create_users</code></td><td>Première tranche payée, toutes parts comprises — <code>auth=oauth2</code>, sans mot de passe</td></tr><tr><td><code>core_user_update_users</code></td><td>Changement de statut : suspension, réactivation, Canopé</td></tr><tr><td><code>enrol_manual_enrol_users</code></td><td>Inscription au cours de la cohorte, ou au cours Parcours Canopé à la certification</td></tr><tr><td><code>enrol_manual_unenrol_users</code></td><td>Abandon, ou bascule Canopé</td></tr><tr><td><code>core_user_get_users_by_field</code></td><td>Retrouver un compte Moodle par email, pour rendre un rejeu idempotent</td></tr></tbody></table><p>Les changements passent par une <strong>file rejouable</strong> (<code>integration_events</code>). Un échec reste en attente avec son erreur ; l&#39;Administrateur est alerté au 5e échec. <code>seve:sync</code> envoie la file chaque minute, dans l&#39;ordre pour un même compte.</p><h3 id="partenaires-et-messages" tabindex="-1">Partenaires et messages <a class="header-anchor" href="#partenaires-et-messages" aria-label="Permalink to &quot;Partenaires et messages&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Fonction</th><th>Déclencheur</th></tr></thead><tbody><tr><td><code>core_course_get_courses</code> / <code>core_course_update_courses</code></td><td><code>seve:partners</code>, chaque heure : bloc « Partenaires » du résumé du cours, sans toucher au reste</td></tr><tr><td><code>core_message_send_instant_messages</code></td><td>Annonce ou rappel à un compte ayant un identifiant Moodle</td></tr></tbody></table><h3 id="remontee" tabindex="-1">Remontée <a class="header-anchor" href="#remontee" aria-label="Permalink to &quot;Remontée&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Fonction</th><th>Alimente</th><th>Fréquence</th></tr></thead><tbody><tr><td><code>core_completion_get_course_completion_status</code></td><td>Progression</td><td>Planifiée</td></tr><tr><td><code>gradereport_user_get_grade_items</code></td><td>Notes par bloc (<code>KURA-BLOC-{id}</code>)</td><td><code>seve:pull</code>, chaque heure</td></tr><tr><td><code>core_course_get_contents</code> + <code>mod_attendance_get_sessions</code></td><td>Présence</td><td><code>seve:pull</code>, chaque heure</td></tr></tbody></table><p>Correspondance des statuts de présence : <code>P</code> présent ; <code>L</code> ou <code>R</code> retard ; <code>A</code>, <code>E</code> et tout autre absent. Une absence excusée reste une absence pour le seuil de 30 %.</p><h2 id="whatsapp-business-cloud-api" tabindex="-1">WhatsApp Business Cloud API <a class="header-anchor" href="#whatsapp-business-cloud-api" aria-label="Permalink to &quot;WhatsApp Business Cloud API&quot;">​</a></h2><p><code>POST https://graph.facebook.com/{WHATSAPP_API_VERSION}/{WHATSAPP_PHONE_NUMBER_ID}/messages</code>, avec <code>Authorization: Bearer {WHATSAPP_TOKEN}</code>. Message de type <code>template</code>, dans la langue du destinataire (<code>fr</code> ou <code>en</code>).</p><table tabindex="0"><thead><tr><th>Modèle</th><th>Notification</th></tr></thead><tbody><tr><td><code>kura_invoice_reminder</code></td><td>Rappel d&#39;échéance (J-15, J-7, J-1)</td></tr><tr><td><code>kura_invoice_unpaid</code></td><td>Rappel J+1</td></tr><tr><td><code>kura_invoice_overdue</code></td><td>Passage en retard et moratoire</td></tr><tr><td><code>kura_access_suspended</code></td><td>Suspension J+30</td></tr><tr><td><code>kura_access_restored</code></td><td>Réactivation</td></tr><tr><td><code>kura_candidature_admitted</code></td><td>Décision « admis »</td></tr><tr><td><code>kura_candidature_refused</code></td><td>Décision « refusé »</td></tr><tr><td><code>kura_candidature_overdue</code></td><td>Étape de candidature en retard</td></tr></tbody></table><p>Tant que <code>WHATSAPP_TOKEN</code> et <code>WHATSAPP_PHONE_NUMBER_ID</code> sont vides, les messages partent uniquement par email. Un échec WhatsApp n&#39;empêche pas l&#39;email.</p><h2 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h2><p>Un moteur unique, trois canaux :</p><table tabindex="0"><thead><tr><th>Canal</th><th>Quand</th></tr></thead><tbody><tr><td>Email</td><td>Toujours</td></tr><tr><td>Sève</td><td>Comptes ouverts dans Sève (message Moodle du compte de service)</td></tr><tr><td>WhatsApp</td><td>Rappels de paiement et d&#39;admission, si le compte a un numéro</td></tr></tbody></table><p>Chaque envoi est enregistré dans <code>notification_deliveries</code> (destinataire, type, canal, statut, erreur, date). Le journal est filtrable par canal et statut, avec le nombre d&#39;échecs des 30 derniers jours.</p><p>Déclencheurs : paiement (J-15/J-7/J-1, J+1, retard, suspension, réactivation), admission (entretien, test, décision), rôles, certification, présence, formation B2B, mise en relation, événements, financement d&#39;événement, partenariats et documents générés.</p><h2 id="paiement-en-ligne-prevu" tabindex="-1">Paiement en ligne (prévu) <a class="header-anchor" href="#paiement-en-ligne-prevu" aria-label="Permalink to &quot;Paiement en ligne (prévu)&quot;">​</a></h2><p>PayGate (Flooz, T-Money) est le prestataire retenu par l&#39;ADR-006. Le contrat prévoit un retour sur <code>POST /api/paiements/callback</code>, qui mettra à jour la facture et le paiement, puis déclenchera les effets : provisionnement Sève quand toutes les parts de la première tranche sont payées, levée de suspension, commission d&#39;apporteur.</p><p>Tant que ce branchement n&#39;est pas fait dans <code>kura-web</code>, les paiements sont saisis manuellement par le Coordinateur et aucun appelant externe ne touche aux factures.</p><h2 id="commandes-et-planification" tabindex="-1">Commandes et planification <a class="header-anchor" href="#commandes-et-planification" aria-label="Permalink to &quot;Commandes et planification&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Commande</th><th>Fréquence</th><th>Rôle</th></tr></thead><tbody><tr><td><code>seve:sync</code></td><td>Chaque minute</td><td>Envoie les changements en attente vers Sève</td></tr><tr><td><code>seve:pull</code></td><td>Chaque heure</td><td>Relit présence et notes des cohortes en cours</td></tr><tr><td><code>seve:partners</code></td><td>Chaque heure</td><td>Met à jour le bloc « Partenaires » des cours</td></tr><tr><td><code>billing:run</code></td><td>Quotidienne</td><td>Émet les tranches dues, relance, moratoires, suspensions</td></tr><tr><td><code>events:run</code></td><td>Horaire</td><td>Annule les inscriptions non payées à 48 h</td></tr><tr><td><code>cohorts:advance</code></td><td>Quotidienne</td><td>Démarre et termine les cohortes</td></tr><tr><td><code>candidatures:remind</code></td><td>Quotidienne</td><td>Relance les étapes de candidature en retard</td></tr><tr><td><code>candidatures:anonymize</code></td><td>Quotidienne</td><td>Anonymise les candidatures refusées depuis 12 mois</td></tr><tr><td><code>accounts:deactivate-inactive</code></td><td>Quotidienne</td><td>Désactive les comptes inactifs depuis un an</td></tr><tr><td><code>partnerships:end</code></td><td>Quotidienne</td><td>Termine les partenariats échus</td></tr><tr><td><code>passport:purge</code></td><td>Quotidienne</td><td>Purge les jetons OAuth expirés</td></tr></tbody></table>',36)])])}const m=t(r,[["render",n]]);export{h as __pageData,m as default};
